/** Three-tier ladder for chadhava offerings. */
function chadhavaPackages(anchor: number, tiers: { en: string; hi: string }[]): PackageSeed[] {
  const single = shubh(anchor);
  const couple = shubh(anchor * 1.9);
  const family = shubh(anchor * 3.2);
  return [
    {
      slug: "single",
      nameEn: "Basic Chadhava",
      nameHi: "सामान्य चढ़ावा",
      descriptionEn: tiers[0].en,
      descriptionHi: tiers[0].hi,
      price: single,
      compareAtPrice: cmp(single),
      maxDevotees: 1,
      featuresEn: ["Offered in your name and gotra", "Photograph of the offering at the shrine", "Returned prasad couriered to you"],
      featuresHi: ["आपके नाम एवं गोत्र से अर्पण", "मंदिर में अर्पण का छायाचित्र", "लौटा प्रसाद आपको कूरियर"],
      popular: false,
    },
    {
      slug: "couple",
      nameEn: "Standard Chadhava",
      nameHi: "मानक चढ़ावा",
      descriptionEn: tiers[1].en,
      descriptionHi: tiers[1].hi,
      price: couple,
      compareAtPrice: cmp(couple),
      maxDevotees: 2,
      featuresEn: [
        "Larger offering with an additional seva",
        "Photographs and a short video at the sanctum",
        "Prasad box with the temple's seva slip",
      ],
      featuresHi: [
        "अतिरिक्त सेवा सहित बड़ा अर्पण",
        "गर्भगृह पर छायाचित्र एवं लघु वीडियो",
        "मंदिर की सेवा पर्ची सहित प्रसाद बॉक्स",
      ],
      popular: true,
    },
    {
      slug: "family",
      nameEn: "Grand Chadhava",
      nameHi: "विशेष चढ़ावा",
      descriptionEn: tiers[2].en,
      descriptionHi: tiers[2].hi,
      price: family,
      compareAtPrice: cmp(family),
      maxDevotees: 4,
      featuresEn: [
        "The complete offering with archana in four names",
        "Full video of the offering and the aarti",
        "Large prasad hamper couriered to your address",
        "Deep daan and annadaan performed on your behalf",
      ],
      featuresHi: [
        "चार नामों से अर्चना सहित संपूर्ण अर्पण",
        "अर्पण एवं आरती का पूर्ण वीडियो",
        "आपके पते पर बड़ा प्रसाद हैंपर कूरियर",
        "आपकी ओर से दीपदान एवं अन्नदान",
      ],
      popular: false,
    },
  ];
}

