    descriptionHi:
      "जन्म के ग्यारहवें अथवा बारहवें दिन — अथवा जिस दिन आपके परिवार की परंपरा हो — शिशु को पहली बार नाम दिया जाता है, और शास्त्र कहते हैं कि अक्षर उस नक्षत्र के अनुसार हो जिसमें शिशु का जन्म हुआ। हमारे पंडित जी जन्म कुंडली बनाकर आपको सही राशि, नक्षत्र, चरण तथा उससे निकलने वाला अक्षर बताते हैं, और उसी अक्षर के नामों की अर्थ सहित सूची देते हैं। विधि में गणेश एवं नवग्रह पूजन, शिशु को सूर्य दर्शन, शिशु के दाहिने कान में नाम का उच्चारण तथा शिशु की आयु एवं आरोग्य हेतु लघु हवन सम्मिलित हैं। नाम अक्षत भरी थाली में लिखा जाता है और घर के बड़े शिशु को आशीर्वाद देते हैं।",
