    taglineEn: "The first tonsure, done the traditional way",
    taglineHi: "पहला केश उतारना, परंपरागत विधि से",
    descriptionEn:
      "Chudakarma is the eighth sanskar, performed in the first, third or fifth year, when the hair a child was born with is offered and fresh hair is allowed to grow. Our pandit takes the sankalp with the child seated in the mother's or maternal uncle's lap, performs Ganesh and kul devta poojan, sanctifies the water and the razor, and the first lock is cut by the elder while the mantras are chanted. Havan follows, then the child's head is washed with turmeric water and gangajal and a tilak of sandal is applied. The offered hair is collected in a leaf-plate for you to immerse at a river or temple, and a small daan is made in the child's name. If you prefer to hold it at a temple such as Salasar or Khatu instead of at home, tell us and we arrange the vidhi there.",
    descriptionHi:
      "चूड़ाकर्म आठवाँ संस्कार है, जो पहले, तीसरे अथवा पाँचवें वर्ष में किया जाता है, जब जन्म के केश अर्पित कर नए केशों को उगने दिया जाता है। हमारे पंडित जी शिशु को माता अथवा मामा की गोद में बिठाकर संकल्प लेते हैं, गणेश एवं कुल देवता पूजन करते हैं, जल एवं क्षुर का अभिमंत्रण करते हैं, और मंत्रोच्चार के बीच बड़े द्वारा प्रथम केश काटा जाता है। तत्पश्चात हवन होता है, फिर शिशु का सिर हल्दी जल एवं गंगाजल से धोकर चंदन का तिलक लगाया जाता है। अर्पित केश पत्तल में एकत्र कर आपको दिए जाते हैं ताकि नदी अथवा मंदिर में प्रवाहित कर सकें, और शिशु के नाम से लघु दान होता है। यदि आप इसे घर के बजाय सालासर अथवा खाटू जैसे मंदिर में कराना चाहें तो बताएँ, हम वहाँ विधि की व्यवस्था कराते हैं।",
