    descriptionEn:
      "Annaprashan is the sanskar of the first solid food, kept in the sixth or eighth month for a boy and the fifth or seventh for a girl, on a day the moon and the tithi are favourable. Our pandit performs Ganesh poojan and a short navgrah shanti, the kheer is cooked and first offered to the deity and to Agni, and then the maternal uncle or the father places the first spoonful in the child's mouth with the annaprashan mantra. Afterwards the family lays out the traditional thali of objects — a book, a coin, a pen, earth and a tulsi leaf — and lets the child choose one, a gentle old custom that everyone enjoys. The vidhi ends with blessings from the elders and prasad for the guests. It is short, warm and easy on the baby.",
    descriptionHi:
      "अन्नप्राशन प्रथम अन्न ग्रहण का संस्कार है, जो बालक हेतु छठे अथवा आठवें मास और बालिका हेतु पाँचवें अथवा सातवें मास में, चंद्रमा एवं तिथि के अनुकूल दिन किया जाता है। हमारे पंडित जी गणेश पूजन एवं लघु नवग्रह शांति करते हैं, खीर बनाकर पहले देवता एवं अग्नि को अर्पित की जाती है, फिर मामा अथवा पिता अन्नप्राशन मंत्र के साथ शिशु के मुख में प्रथम ग्रास रखते हैं। तत्पश्चात परिवार परंपरागत थाली सजाता है — पुस्तक, सिक्का, कलम, मिट्टी एवं तुलसी दल — और शिशु को कोई एक चुनने देता है, यह पुरानी प्यारी परंपरा सभी को भाती है। विधि बड़ों के आशीर्वाद एवं अतिथियों को प्रसाद के साथ पूर्ण होती है। यह छोटा, आत्मीय और शिशु के लिए सहज अनुष्ठान है।",
