    descriptionHi:
      "बर्बरीक ने महाभारत आरंभ होने से पूर्व अपना शीश दान किया, और श्रीकृष्ण ने उन्हें वरदान दिया कि कलियुग में वे श्याम के रूप में पूजे जाएँगे — वह जो हारने वाले के साथ खड़ा रहता है। निशान, वह त्रिकोण ध्वज जो रींगस से खाटू तक पैदल ले जाया जाता है, उनका विशिष्ट अर्पण है, और फाल्गुन में लाखों भक्त वह मार्ग नंगे पाँव चलते हैं। हमारा सेवक आपका निशान परंपरागत मार्ग से ले जाता है, आपके नाम एवं गोत्र के उच्चारण सहित उसे मंदिर शिखर पर फहरवाता है, और इत्र, केसर-दूध प्रसाद तथा आपके लहराते ध्वज का छायाचित्र लौटाता है। जो पदयात्रा नहीं कर सकते वे वर्षभर इसी प्रकार अपना निशान भेजते हैं। श्याम बाबा 'हारे का सहारा' कहलाते हैं — और उनके भक्त इसी भाव से माँगते हैं।",
