    descriptionEn:
      "The face drawn on the Mahakal lingam in bhang, chandan and dry fruit is one of the most recognised images in Bharat, and it changes with the day — Monday's Chandra shringar, Shravan's Umā-Mahesh, Shivratri's Sehra. Our sevak arranges the bhang-chandan shringar in your name with the temple's own shringar sevaks, offers bel patra, bhasma, aak, dhatura and panchamrit, and captures the photographs of the completed shringar before the pat closes. Nowhere else does Shiva look quite like this, and devotees who have stood in the Mahakal darshan queue know why a photograph of your own shringar day is worth keeping. Monday, Shravan Somvar and Mahashivratri are the days people ask for first.",
    descriptionHi:
      "महाकाल के लिंग पर भांग, चंदन एवं मेवे से बनाया गया मुखारविंद भारत की सर्वाधिक पहचानी छवियों में है, और वह दिन के अनुसार बदलता है — सोमवार का चंद्र शृंगार, श्रावण का उमा-महेश, शिवरात्रि का सेहरा। हमारा सेवक मंदिर के अपने शृंगार सेवकों के साथ आपके नाम से भांग-चंदन शृंगार की व्यवस्था कराता है, बेलपत्र, भस्म, आक, धतूरा एवं पंचामृत अर्पित करता है, और पट बंद होने से पूर्व पूर्ण शृंगार के छायाचित्र लेता है। और कहीं शिव ऐसे नहीं दिखते, और जो महाकाल दर्शन की पंक्ति में खड़े रहे हैं वे जानते हैं कि अपने शृंगार दिवस का छायाचित्र क्यों सहेजने योग्य है। सोमवार, श्रावण सोमवार एवं महाशिवरात्रि — लोग सबसे पहले यही दिन माँगते हैं।",
